function resolveSpec(fromFile, spec) {
  if (!spec.startsWith('.')) return null;
  const p = relative(ROOT, resolve(ROOT, dirname(fromFile), spec));
  return src.has(p) ? p : (p.endsWith('.md') || p.endsWith('.json') ? null : p);
