function splitNames(s) {
  return s.split(',').map(x => x.trim()).filter(Boolean).map(x => {
    const m = x.match(/^(?:type\s+)?([\w$*]+)(?:\s+as\s+([\w$]+))?$/);
    return m ? { orig: m[1], local: m[2] || m[1] } : null;
  }).filter(Boolean);
