const mods = new Map(); // file -> { imports: Map<local,{file,orig}>, starFrom: [file], exports: Map<exported, {kind, local, file?, orig?}>, decls: Map<name,{body,line,endLine}>, moduleBody }
for (const [f, text] of src) {
  const stmts = joinStatements(text);
  const imports = new Map();
  const starFrom = [];
  const exports = new Map();
  const declLines = new Set();

  for (const { text: l, line } of stmts) {
    let m;
