const RE_REEXPORT_NAMED = /^export\s*\{([^}]*)\}\s*from\s*['"]([^'"]+)['"]/;
const RE_REEXPORT_STAR = /^export\s*\*\s*(?:as\s+([\w$]+)\s*)?from\s*['"]([^'"]+)['"]/;
const RE_LOCAL_EXPORT = /^export\s*\{([^}]*)\}\s*;?\s*$/;
const RE_DECL = /^(export\s+)?(?:(async\s+)?function\s*\*?\s*([\w$]+)|class\s+([\w$]+)|(?:const|let|var)\s+([\w$]+))/;

function joinStatements(text) {
  // collapse multi-line import/export braces into single logical lines, keeping start offsets
  const lines = text.split('\n');
  const out = [];
  let i = 0;
  while (i < lines.length) {
    let l = lines[i];
    const start = i;
    if (/^\s*(import|export)\b/.test(l) && l.includes('{') && !l.includes('}')) {
      while (i + 1 < lines.length && !lines[i].includes('}')) { i++; l += ' ' + lines[i].trim(); }
    }
    out.push({ text: l, line: start });
    i++;
  }
  return out;
