while (queue.length) {
  const { file, sym, level } = queue.shift();
  const mod = mods.get(file);
  if (!mod) continue;
  let body = null;
  if (sym === '*MODULE*') body = mod.moduleBody;
  else if (sym === '*') { // namespace: everything
    for (const n of mod.exports.keys()) addSym(file, n, level);
    for (const n of mod.decls.keys()) addSym(file, n, level);
