    if (liveExp.length) out.push(`    used: ${liveExp.join(', ')}`);
    if (deadExp.length) out.push(`    unused-from-public: ${deadExp.join(', ')}`);
  }
}
const unreached = packFiles.filter(f => !fileLevel.has(f));
out.push(`\n===== NOT REACHABLE from public/ — ${unreached.length} files =====`);
for (const f of unreached.sort()) out.push(`  ${f}`);
