import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { renderSurfaceReport, publishedNames, consumerBucket, readSurfaceUse } from '../pack-surface.mjs';

// Maintained the way packs/directory.GENERATED.md is (engine-tests/pack-directory.test.mjs):
// locally this test rewrites the artifact, under CI it only asserts, so a change that
// widens a published surface without regenerating fails in ITS OWN pull request rather
// than in a later sweep's.
const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const PACK_DIR = 'packs/claudinite-tasks';
const REPORT = `${PACK_DIR}/public/SURFACE.GENERATED.md`;

// The tracked tree, read once. Only text the surface can be named from is worth
// scanning, and the report itself is excluded — it names every module, so including it
// would make every module read as consumed by the canon.
function trackedText() {
  const paths = execFileSync('git', ['ls-files'], { cwd: ROOT, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 }).trim().split('\n');
  const files = new Map();
  for (const p of paths) {
    if (p === REPORT) continue;
    if (!/\.(mjs|js|json|md|yml|yaml)$/.test(p)) continue;
    try { files.set(p, readFileSync(join(ROOT, p), 'utf8')); } catch { /* unreadable in a partial checkout */ }
  }
  return files;
}

test(`${REPORT} is current with the tracked tree`, () => {
  const files = trackedText();
